{
  "candidate_edge_types": [
    {
      "name": "ATTEMPTS_TO_REPAIR",
      "definition": "A subsequent agent action attempts to resolve a failure or error identified during an earlier execution step.",
      "source_description": "An earlier observed execution failure or error.",
      "target_description": "A subsequent agent action intended to resolve that failure."
    },
    {
      "name": "INVESTIGATES_UNCERTAINTY",
      "definition": "A diagnostic agent action is performed to resolve an ambiguity or unclear interpretation left by an earlier observation before committing to a modeling or processing step.",
      "source_description": "An earlier observation whose meaning or interpretation is unclear or ambiguous.",
      "target_description": "A subsequent diagnostic action intended to clarify or characterize that observation."
    },
    {
      "name": "USES_PRIOR_OBSERVATION_AS_BASIS",
      "definition": "A subsequent agent action is constructed using information obtained from an earlier execution observation, such as derived parameters, discovered values, or structural insight.",
      "source_description": "An earlier observation containing information the agent relies on.",
      "target_description": "A subsequent agent action that incorporates or is based on that information."
    },
    {
      "name": "VERIFIES_PRODUCED_ARTIFACT",
      "definition": "A subsequent agent action inspects the content of an artifact produced by an earlier action in order to confirm that it was written and contains the expected content.",
      "source_description": "An artifact or output produced by an earlier agent action.",
      "target_description": "A subsequent inspection action verifying that artifact's contents."
    },
    {
      "name": "COMPLETES_TASK_AFTER_VERIFICATION",
      "definition": "An agent terminates the task based on the confirmation obtained from a prior verification that the required output exists and is correct.",
      "source_description": "A successful verification observation confirming the required output.",
      "target_description": "A task completion action that ends execution."
    }
  ]
}

